import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));describe("Arikamedu Ancient Port Explorer Tests",()=>{it("HTML contains historical overview, location, timeline, trade routes, and discoveries",()=>{const e=readFileSync(resolve(__dirname,"../../arikamedu-port-explorer/index.html"),"utf-8");expect(e).toContain('id="overview"'),expect(e).toContain('id="location-timeline"'),expect(e).toContain('id="trade-routes"'),expect(e).toContain('id="findings"'),expect(e).toContain('id="gallery"'),expect(e).toContain('id="references"'),expect(e).toContain("Arikamedu"),expect(e).toContain("Poduke"),expect(e).toContain("Wheeler")}),it("CSS stylesheet exists and defines port styling tokens",()=>{const e=readFileSync(resolve(__dirname,"../../arikamedu-port-explorer/style.css"),"utf-8");expect(e).toContain("--port-laterite-light"),expect(e).toContain(".port-main"),expect(e).toContain(".port-hero")}),it("JavaScript module initializes cleanly",()=>{const e=readFileSync(resolve(__dirname,"../../arikamedu-port-explorer/script.js"),"utf-8");expect(e).toContain("ArikameduPortExplorer"),expect(e).toContain("setupGalleryModal")})});